import fs from 'node:fs';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';const root=process.env.ROOT,sha=x=>createHash('sha256').update(x).digest('hex'),old=JSON.parse(fs.readFileSync(root+'/parser-patch-plan.json')),r={at:new Date().toISOString(),files:[]};fs.copyFileSync(root+'/parser-patch-plan.json',root+'/parser-patch-plan-v1.json');fs.mkdirSync(root+'/parser-before-v2',{recursive:true});fs.mkdirSync(root+'/parser-candidate-v2',{recursive:true});for(const f of old.files){const before=fs.readFileSync(f.file,'utf8');assert.equal(sha(before),f.afterSha);let after=before;if(f.file.endsWith('/newsStrictPublication.mjs')){const a="[a.url,a.mainEntityOfPage?.['@id'],a.mainEntityOfPage?.url,typeof",b="[a.url,a.mainEntityOfPage?.['@id'],!a.url&&!a.mainEntityOfPage?.['@id']?a.mainEntityOfPage?.url:null,typeof";assert.equal(after.split(a).length-1,2);after=after.split(a).join(b);}if(f.file.endsWith('/newsPublicationPageIdentity.mjs')){const a="[a.url, a.mainEntityOfPage?.['@id'], a.mainEntityOfPage?.url, typeof",b="[a.url, a.mainEntityOfPage?.['@id'], !a.url && !a.mainEntityOfPage?.['@id'] ? a.mainEntityOfPage?.url : null, typeof";assert.equal(after.split(a).length-1,1);after=after.replace(a,b);}const name=f.file.split('/').at(-1),backup=root+'/parser-before-v2/'+name,candidate=root+'/parser-candidate-v2/'+name;fs.writeFileSync(backup,before,{mode:0o600});fs.writeFileSync(candidate,after,{mode:0o600});r.files.push({file:f.file,backup,candidate,beforeSha:sha(before),afterSha:sha(after)});}fs.writeFileSync(root+'/parser-patch-plan.json',JSON.stringify(r,null,2));console.log(JSON.stringify({prepared:true,files:r.files.length}));
